import{_ as t,c as e,o as a,a2 as d}from"./chunks/framework.DdOM6S6U.js";const m=JSON.parse('{"title":"Repository Logic Traits","description":"","frontmatter":{"sidebarPos":1,"sidebarTitle":"Overview"},"headers":[],"relativePath":"system-reference/backend/repository-traits/overview.md","filePath":"system-reference/backend/repository-traits/overview.md","lastUpdated":1777449208000}'),r={name:"system-reference/backend/repository-traits/overview.md"},o=d('<h1 id="repository-logic-traits" tabindex="-1">Repository Logic Traits <a class="header-anchor" href="#repository-logic-traits" aria-label="Permalink to &quot;Repository Logic Traits&quot;">​</a></h1><p>Repository traits extend the base <code>Repository</code> class with domain-specific persistence logic. While <a href="./../entity-traits/overview">Entity Traits</a> define model-level behavior (relationships, scopes, accessors), repository traits handle <strong>how data flows in and out</strong> — form field hydration, after-save side effects, column detection, table filters, and caching.</p><p>Every repository trait follows a <strong>naming convention</strong> that the base <code>Repository</code> automatically discovers and invokes at the correct lifecycle stage:</p><table><thead><tr><th>Convention</th><th>Signature</th><th>When Called</th></tr></thead><tbody><tr><td><code>setColumns{Trait}</code></td><td><code>($columns, $inputs): array</code></td><td>During boot — registers which form input names this trait manages</td></tr><tr><td><code>prepareFieldsBeforeCreate{Trait}</code></td><td><code>($fields): array</code></td><td>Before a new record is inserted</td></tr><tr><td><code>prepareFieldsBeforeSave{Trait}</code></td><td><code>($object, $fields): array</code></td><td>Before any save (create or update)</td></tr><tr><td><code>beforeSave{Trait}</code></td><td><code>($object, $fields): void</code></td><td>Just before the Eloquent <code>save()</code> call</td></tr><tr><td><code>afterSave{Trait}</code></td><td><code>($object, $fields): void</code></td><td>Immediately after <code>save()</code> — side effects (pivot syncing, file moves, etc.)</td></tr><tr><td><code>hydrate{Trait}</code></td><td><code>($object, $fields): Model</code></td><td>Sets in-memory relationships before save (preview/validation)</td></tr><tr><td><code>getFormFields{Trait}</code></td><td><code>($object, $fields, $schema): array</code></td><td>Populates form fields when editing an existing record</td></tr><tr><td><code>afterDelete{Trait}</code></td><td><code>($object): void</code></td><td>Cleanup after soft-delete</td></tr><tr><td><code>afterRestore{Trait}</code></td><td><code>($object): void</code></td><td>Restoration hook</td></tr><tr><td><code>filter{Trait}</code></td><td><code>($query, &amp;$scopes): void</code></td><td>Applies default query scopes/filters on index listings</td></tr><tr><td><code>order{Trait}</code></td><td><code>($query, &amp;$orders): void</code></td><td>Applies ordering logic</td></tr><tr><td><code>getTableFilters{Trait}</code></td><td><code>($scope): array</code></td><td>Returns filter tab definitions for the data table UI</td></tr><tr><td><code>getFormActions{Trait}</code></td><td><code>($scope): array</code></td><td>Returns form action button definitions</td></tr></tbody></table><h2 id="trait-groups" tabindex="-1">Trait Groups <a class="header-anchor" href="#trait-groups" aria-label="Permalink to &quot;Trait Groups&quot;">​</a></h2><table><thead><tr><th>Group</th><th>Namespace</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="#media-traits">Media</a></td><td><code>Repositories\\Traits\\</code></td><td>Persist files, images, and Filepond uploads</td></tr><tr><td><a href="#relationship-traits">Relationships</a></td><td><code>Repositories\\Traits\\</code></td><td>Save assignment, authorization, and creator data</td></tr><tr><td><a href="#content-traits">Content</a></td><td><code>Repositories\\Traits\\</code></td><td>Slugs, translations, tags, and spreadable JSON</td></tr><tr><td><a href="#state-traits">State</a></td><td><code>Repositories\\Traits\\</code></td><td>State machine filter lists and table filters</td></tr><tr><td><a href="#payment-traits">Payment</a></td><td><code>Repositories\\Traits\\</code></td><td>Price and payment record management</td></tr><tr><td><a href="#process-traits">Processes</a></td><td><code>Repositories\\Traits\\</code></td><td>Workflow processes and repeater blocks</td></tr><tr><td><a href="#oauth-traits">OAuth</a></td><td><code>Repositories\\Traits\\</code></td><td>Social login user lookup and creation</td></tr><tr><td><a href="#logic-traits">Logic</a></td><td><code>Repositories\\Logic\\</code></td><td>Caching layer and trait introspection</td></tr></tbody></table><hr><h2 id="media-traits" tabindex="-1">Media Traits <a class="header-anchor" href="#media-traits" aria-label="Permalink to &quot;Media Traits&quot;">​</a></h2><table><thead><tr><th>Trait</th><th>Page</th><th>Summary</th></tr></thead><tbody><tr><td><code>FilepondsTrait</code></td><td><a href="./media">Media →</a></td><td>Persists Filepond temporary uploads to permanent storage after save</td></tr><tr><td><code>FilesTrait</code></td><td><a href="./media">Media →</a></td><td>Syncs <code>File</code> model attachments through the <code>fileables</code> pivot</td></tr><tr><td><code>ImagesTrait</code></td><td><a href="./media">Media →</a></td><td>Syncs <code>Media</code> model attachments through the <code>mediables</code> pivot</td></tr></tbody></table><h2 id="relationship-traits" tabindex="-1">Relationship Traits <a class="header-anchor" href="#relationship-traits" aria-label="Permalink to &quot;Relationship Traits&quot;">​</a></h2><table><thead><tr><th>Trait</th><th>Page</th><th>Summary</th></tr></thead><tbody><tr><td><code>AssignmentTrait</code></td><td><a href="./relationships">Relationships →</a></td><td>Provides assignment form fields, default filters, and table filter tabs</td></tr><tr><td><code>AuthorizableTrait</code></td><td><a href="./relationships">Relationships →</a></td><td>Hydrates authorization record fields and adds authorized/unauthorized filters</td></tr><tr><td><code>CreatorTrait</code></td><td><a href="./relationships">Relationships →</a></td><td>Applies creator-based access scope and prepends creator form input</td></tr></tbody></table><h2 id="content-traits" tabindex="-1">Content Traits <a class="header-anchor" href="#content-traits" aria-label="Permalink to &quot;Content Traits&quot;">​</a></h2><table><thead><tr><th>Trait</th><th>Page</th><th>Summary</th></tr></thead><tbody><tr><td><code>SlugsTrait</code></td><td><a href="./content">Content →</a></td><td>Persists locale-aware slugs and resolves slug-based lookups</td></tr><tr><td><code>SpreadableTrait</code></td><td><a href="./content">Content →</a></td><td>Moves spreadable fields into/from the JSON <code>Spread</code> record</td></tr><tr><td><code>TagsTrait</code></td><td><a href="./content">Content →</a></td><td>Syncs tags (with locale support) and provides tag query helpers</td></tr><tr><td><code>TranslationsTrait</code></td><td><a href="./content">Content →</a></td><td>Prepares per-locale translation fields and handles translatable search/ordering</td></tr></tbody></table><h2 id="state-traits" tabindex="-1">State Traits <a class="header-anchor" href="#state-traits" aria-label="Permalink to &quot;State Traits&quot;">​</a></h2><table><thead><tr><th>Trait</th><th>Page</th><th>Summary</th></tr></thead><tbody><tr><td><code>StateableTrait</code></td><td><a href="./state">State →</a></td><td>Builds state filter lists and table filter tabs from the model&#39;s state machine</td></tr></tbody></table><h2 id="payment-traits" tabindex="-1">Payment Traits <a class="header-anchor" href="#payment-traits" aria-label="Permalink to &quot;Payment Traits&quot;">​</a></h2><table><thead><tr><th>Trait</th><th>Page</th><th>Summary</th></tr></thead><tbody><tr><td><code>PricesTrait</code></td><td><a href="./payment">Payment →</a></td><td>Creates, updates, and deletes morphed <code>Price</code> records with currency exchange</td></tr><tr><td><code>PaymentTrait</code></td><td><a href="./payment">Payment →</a></td><td>Orchestrates payment price calculation, payment service integration, and pay action</td></tr></tbody></table><h2 id="process-traits" tabindex="-1">Process Traits <a class="header-anchor" href="#process-traits" aria-label="Permalink to &quot;Process Traits&quot;">​</a></h2><table><thead><tr><th>Trait</th><th>Page</th><th>Summary</th></tr></thead><tbody><tr><td><code>ProcessableTrait</code></td><td><a href="./processes">Processes →</a></td><td>Auto-creates workflow processes and hydrates process form fields</td></tr><tr><td><code>RepeatersTrait</code></td><td><a href="./processes">Processes →</a></td><td>Persists nested repeater JSON blocks with locale and media support</td></tr></tbody></table><h2 id="oauth-traits" tabindex="-1">OAuth Traits <a class="header-anchor" href="#oauth-traits" aria-label="Permalink to &quot;OAuth Traits&quot;">​</a></h2><table><thead><tr><th>Trait</th><th>Page</th><th>Summary</th></tr></thead><tbody><tr><td><code>OauthTrait</code></td><td><a href="./oauth">OAuth →</a></td><td>Looks up, links, and creates users from OAuth provider data</td></tr></tbody></table><h2 id="logic-traits" tabindex="-1">Logic Traits <a class="header-anchor" href="#logic-traits" aria-label="Permalink to &quot;Logic Traits&quot;">​</a></h2><table><thead><tr><th>Trait</th><th>Page</th><th>Summary</th></tr></thead><tbody><tr><td><code>QueryBuilder</code></td><td><a href="./logic/QueryBuilder">Logic/QueryBuilder →</a></td><td>Paginated listing, single-record lookup, multi-ID fetching, and flat-list helpers</td></tr><tr><td><code>MethodTransformers</code></td><td><a href="./logic/MethodTransformers">Logic/MethodTransformers →</a></td><td>Lifecycle hook dispatcher — fans out to every <code>{hookName}{Trait}</code> method across loaded traits</td></tr><tr><td><code>Relationships</code></td><td><a href="./logic/Relationships">Logic/Relationships →</a></td><td>Syncs all Eloquent relationship types (BelongsToMany, HasMany, MorphMany, MorphTo, MorphToMany) on save</td></tr><tr><td><code>RelationshipHelpers</code></td><td><a href="./logic/RelationshipHelpers">Logic/RelationshipHelpers →</a></td><td>Reflection-based relationship discovery and foreign key resolution</td></tr><tr><td><code>Schema</code></td><td><a href="./logic/Schema">Logic/Schema →</a></td><td>Active schema management and input chunking helpers</td></tr><tr><td><code>CountBuilders</code></td><td><a href="./logic/CountBuilders">Logic/CountBuilders →</a></td><td>Cached aggregate counts for status tabs (all, published, draft, trash)</td></tr><tr><td><code>Dates</code></td><td><a href="./logic/Dates">Logic/Dates →</a></td><td>Normalises date fields to <code>Y-m-d H:i:s</code> before save</td></tr><tr><td><code>DispatchEvents</code></td><td><a href="./logic/DispatchEvents">Logic/DispatchEvents →</a></td><td>Dispatches domain events (create/update/delete/restore) after database commit</td></tr><tr><td><code>CollationSelector</code></td><td><a href="./logic/CollationSelector">Logic/CollationSelector →</a></td><td>Applies explicit MySQL collation to LIKE search queries on text columns</td></tr><tr><td><code>CacheableTrait</code></td><td><a href="./logic/CacheableTrait">Logic/CacheableTrait →</a></td><td>Relationship-aware caching for index and record queries</td></tr><tr><td><code>InspectTraits</code></td><td><a href="./logic/InspectTraits">Logic/InspectTraits →</a></td><td>Runtime introspection — checks whether repository or model uses a given trait</td></tr><tr><td><code>TouchableEloquentModel</code></td><td><a href="./logic/TouchableEloquentModel">Logic/TouchableEloquentModel →</a></td><td>Deferred <code>updated_at</code> touching — fires exactly once after all relationship syncs</td></tr></tbody></table>',23),i=[o];function s(c,n,l,h,p,f){return a(),e("div",null,i)}const b=t(r,[["render",s]]);export{m as __pageData,b as default};
